import{_ as s,C as l,o,c as i,a2 as t,b as r,w as a,a as n,E as c,a3 as h}from"./chunks/framework.CuUVYbLV.js";const _=JSON.parse('{"title":"模型别名","description":"role_config.yaml 的 model_aliases 配置参考——文件位置、三级解析优先级、单跳语义、容错加载、生效时机与排查清单","frontmatter":{"title":"模型别名","description":"role_config.yaml 的 model_aliases 配置参考——文件位置、三级解析优先级、单跳语义、容错加载、生效时机与排查清单"},"headers":[],"relativePath":"03-Reference/model-aliases.md","filePath":"03-Reference/model-aliases.md"}'),p={name:"03-Reference/model-aliases.md"};function E(m,e,g,k,u,b){const d=l("Mermaid");return o(),i("div",null,[e[1]||(e[1]=t(`<h1 id="模型别名-model-aliases" tabindex="-1">模型别名（Model Aliases） <a class="header-anchor" href="#模型别名-model-aliases" aria-label="Permalink to &quot;模型别名（Model Aliases）&quot;">​</a></h1><p>注册中心里的角色常常带着占位模型名发布（如 <code>PLACEHOLDER</code>、<code>YOUR_MODEL_HERE</code>），而不是真实的 <code>provider/model_id</code>。与其逐个改角色的 <code>role.yaml</code>，不如在本地 <code>role_config.yaml</code> 里一次性定义<strong>模型别名（model alias，把占位字符串映射到真实模型的本地配置）</strong>。本页给出配置格式、解析优先级、失败时的降级行为与排查清单。</p><blockquote><p>相关：<a href="/rolebox-docs/03-Reference/role-yaml.html">role.yaml 参考</a>｜<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>｜<a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a></p></blockquote><h2 id="最小示例" tabindex="-1">最小示例 <a class="header-anchor" href="#最小示例" aria-label="Permalink to &quot;最小示例&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {configDir}/role_config.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model_aliases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  PLACEHOLDER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openrouter/anthropic/claude-sonnet-4</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  YOUR_MODEL_HERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic/claude-opus-4</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到：角色加载时 model: PLACEHOLDER 被替换为 openrouter/anthropic/claude-sonnet-4；表内没有、也不属于已知模型的字符串原样透传，并在日志里得到一条 info 提示。</span></span></code></pre></div><p><code>model_aliases</code> 是一个「字符串 → 字符串」映射：key 是 <code>role.yaml</code> 中 <code>model:</code> 写下的占位字符串（精确匹配），value 是真实模型，形如 <code>provider/model_id</code>。把 <code>model:</code> 字符串换算成可用模型标识的组件称为<strong>解析器（resolver）</strong>，它只读取这一个配置键。</p><h2 id="配置文件位置" tabindex="-1">配置文件位置 <a class="header-anchor" href="#配置文件位置" aria-label="Permalink to &quot;配置文件位置&quot;">​</a></h2><p><code>role_config.yaml</code> 放在当前 harness 的配置目录下，即 <code>{configDir}/role_config.yaml</code>：</p><table tabindex="0"><thead><tr><th>Harness</th><th>路径</th><th>配置目录解析</th></tr></thead><tbody><tr><td>opencode</td><td><code>~/.config/opencode/role_config.yaml</code></td><td><code>$XDG_CONFIG_HOME</code> 优先，否则 <code>~/.config/opencode</code></td></tr><tr><td>pi</td><td><code>~/.pi/agent/role_config.yaml</code></td><td><code>$PI_CODING_AGENT_DIR</code> 优先，否则 <code>~/.pi/agent</code></td></tr><tr><td>dsh</td><td><code>~/.dsh/role_config.yaml</code></td><td><code>$DSH_HOME</code> 优先，否则 <code>~/.dsh</code></td></tr></tbody></table><p>在 opencode 上，<code>role_config.yaml</code> 与 <code>opencode.jsonc</code> 同目录——后者同时提供「已知模型」清单（见下节）。三个 harness 的完整目录规则见<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>。</p><h2 id="解析优先级" tabindex="-1">解析优先级 <a class="header-anchor" href="#解析优先级" aria-label="Permalink to &quot;解析优先级&quot;">​</a></h2><p>解析器共 5 个分支：2 个前置守卫 + 3 级优先级。整条链是非破坏性的——任何一级不匹配都返回原字符串，角色加载不会因此失败。</p><table tabindex="0"><thead><tr><th>顺序</th><th>触发条件</th><th>结果</th></tr></thead><tbody><tr><td>守卫 1</td><td><code>model</code> 为空或全空白</td><td>原样返回，不记日志</td></tr><tr><td>守卫 2</td><td>解析器尚未初始化</td><td><code>log.warn</code> + 原样返回</td></tr><tr><td>Priority 1</td><td>命中<strong>已知模型</strong></td><td>原样返回（本身已是规范的 <code>provider/model_id</code>）</td></tr><tr><td>Priority 2</td><td>命中 <code>model_aliases</code></td><td>返回别名映射值（单跳）</td></tr><tr><td>Priority 3</td><td>两者都不命中</td><td><code>log.info</code> 输出提示 + 原样返回</td></tr></tbody></table><p><strong>已知模型（known model，已出现在 <code>{configDir}/opencode.jsonc</code> 的 provider 模型目录中、本身已是规范 ID 的模型）</strong> 与别名分别在每次初始化时从 <code>opencode.jsonc</code> 和 <code>role_config.yaml</code> 一起重新加载。</p>`,15)),(o(),r(h,null,{default:a(()=>[c(d,{id:"mermaid-159",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22role.yaml%20%E7%9A%84%20model%20%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%20--%3E%20B%7B%22%E7%A9%BA%E6%88%96%E5%85%A8%E7%A9%BA%E7%99%BD%3F%22%7D%0A%20%20%20%20B%20--%20%E6%98%AF%20--%3E%20Z%5B%22%E8%BF%94%E5%9B%9E%E5%8E%9F%E5%AD%97%E7%AC%A6%E4%B8%B2%EF%BC%88%E9%80%8F%E4%BC%A0%EF%BC%89%22%5D%0A%20%20%20%20B%20--%20%E5%90%A6%20--%3E%20C%7B%22%E8%A7%A3%E6%9E%90%E5%99%A8%E5%B7%B2%E5%88%9D%E5%A7%8B%E5%8C%96%3F%22%7D%0A%20%20%20%20C%20--%20%E5%90%A6%20--%3E%20W%5B%22log.warn%22%5D%20--%3E%20Z%0A%20%20%20%20C%20--%20%E6%98%AF%20--%3E%20D%7B%22%E5%91%BD%E4%B8%AD%E5%B7%B2%E7%9F%A5%E6%A8%A1%E5%9E%8B%3F%22%7D%0A%20%20%20%20D%20--%20%E6%98%AF%20--%3E%20Z%0A%20%20%20%20D%20--%20%E5%90%A6%20--%3E%20E%7B%22%E5%91%BD%E4%B8%AD%20model_aliases%3F%22%7D%0A%20%20%20%20E%20--%20%E6%98%AF%20--%3E%20F%5B%22%E8%BF%94%E5%9B%9E%E5%8D%95%E8%B7%B3%E5%88%AB%E5%90%8D%E5%80%BC%22%5D%0A%20%20%20%20E%20--%20%E5%90%A6%20--%3E%20G%5B%22log.info%20%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20Z%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="priority-3-的提示日志" tabindex="-1">Priority 3 的提示日志 <a class="header-anchor" href="#priority-3-的提示日志" aria-label="Permalink to &quot;Priority 3 的提示日志&quot;">​</a></h3><p>未识别的值不会导致失败，而是输出一条 <code>log.info</code> 级提示，指出配置位置与 YAML 形状（其中 <code>${model}</code> 为实际模型名）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model &quot;${model}&quot; is not a known model and has no alias configured. Passing through as-is. You can add an alias in role_config.yaml under the &quot;model_aliases&quot; key. Example: model_aliases:</span></span>\n<span class="line"><span>  &quot;${model}&quot;: provider/model_id</span></span></code></pre></div><p>提示级别是 <strong>info</strong>，不是 error，也不是 warn：只有「解析器未初始化」这一守卫使用 <code>log.warn</code>。因此角色加载永远不会因为一个未识别的模型名而中断。</p><h2 id="单跳语义" tabindex="-1">单跳语义 <a class="header-anchor" href="#单跳语义" aria-label="Permalink to &quot;单跳语义&quot;">​</a></h2><p>别名解析只做一次查表，不存在传递链：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model_aliases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  A</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">B</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  B</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">C</span></span></code></pre></div><p><code>A</code> 会被解析成 <code>B</code>，<strong>不会</strong>继续解析成 <code>C</code>。若希望 <code>A</code> 最终落到 <code>C</code>，必须直接写 <code>A: C</code>。</p><h2 id="容错加载" tabindex="-1">容错加载 <a class="header-anchor" href="#容错加载" aria-label="Permalink to &quot;容错加载&quot;">​</a></h2><p>读取 <code>role_config.yaml</code> 的加载器<strong>从不抛错</strong>：任何异常输入都退化成「空映射」或「跳过该条」。</p><table tabindex="0"><thead><tr><th>情况</th><th>行为</th></tr></thead><tbody><tr><td>文件不存在</td><td>返回空映射，不记日志</td></tr><tr><td>YAML 解析失败</td><td><code>log.warn</code> + 空映射</td></tr><tr><td>文档顶层不是对象（含 <code>null</code>）</td><td>空映射</td></tr><tr><td>没有 <code>model_aliases</code> 键，或其值不是对象</td><td>空映射</td></tr><tr><td>别名 key 为空字符串</td><td>跳过该条 + <code>log.warn</code></td></tr><tr><td>别名 value 不是字符串（数字 / 布尔 / <code>null</code> / 数组 / 对象）</td><td>跳过该条 + <code>log.warn</code>（日志含实际类型）</td></tr><tr><td>别名 value 为空字符串</td><td>跳过该条 + <code>log.warn</code></td></tr><tr><td>合法条目</td><td>写入结果映射</td></tr></tbody></table><p>跳过是<strong>逐条</strong>进行的：同一个文件里非法条目被跳过，合法条目照常生效。</p><h2 id="生效时机" tabindex="-1">生效时机 <a class="header-anchor" href="#生效时机" aria-label="Permalink to &quot;生效时机&quot;">​</a></h2><p>模型解析发生在<strong>角色加载期</strong>，不是工具调用期：</p><table tabindex="0"><thead><tr><th>应用点</th><th>说明</th></tr></thead><tbody><tr><td>启动引导</td><td>角色发现之前先初始化解析器，因此加载角色时别名已可用</td></tr><tr><td>角色级 <code>model</code></td><td>仅当 <code>model</code> 是字符串时替换为解析结果</td></tr><tr><td>子代理 <code>model</code></td><td>内联与文件式子代理的模型走同一个解析器</td></tr></tbody></table><h2 id="热重载" tabindex="-1">热重载 <a class="header-anchor" href="#热重载" aria-label="Permalink to &quot;热重载&quot;">​</a></h2><p>每次初始化都会重新加载 <code>opencode.jsonc</code> 与 <code>role_config.yaml</code> <strong>两个</strong>来源，没有幂等检查，也没有惰性初始化。因此编辑 <code>role_config.yaml</code> 后无需重启进程——下一次重载或启动即生效。</p><table tabindex="0"><thead><tr><th>触发场景</th><th>说明</th></tr></thead><tbody><tr><td>opencode 完整热重载</td><td>重载周期内重新初始化解析器</td></tr><tr><td>dsh 角色重载</td><td>重新初始化解析器</td></tr><tr><td>启动引导</td><td>每次启动都会初始化（opencode / pi / dsh 共用同一引导流程）</td></tr></tbody></table><p>若某条调用路径没有经过上述入口，就必须先显式初始化解析器；否则会命中「未初始化」守卫，<code>log.warn</code> 后原样透传。</p><h2 id="排查清单" tabindex="-1">排查清单 <a class="header-anchor" href="#排查清单" aria-label="Permalink to &quot;排查清单&quot;">​</a></h2><ul><li><strong>别名不生效</strong> — key 必须与 <code>role.yaml</code> 中 <code>model:</code> 的字符串<strong>精确相等</strong>（大小写敏感）。</li><li><strong>日志出现 &quot;is not a known model and has no alias configured&quot;</strong> — Priority 3 命中：检查 <code>model_aliases</code> 的键名拼写，以及文件是否位于当前 harness 的配置目录。</li><li><strong>别名指向另一个别名</strong> — 不会递归；把 value 直接写成最终的 <code>provider/model_id</code>。</li><li><strong>条目被丢弃，日志里只有一条 warn</strong> — value 必须是字符串且非空；数字、布尔、<code>null</code>、数组与对象都会被跳过。</li></ul><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><blockquote><p>自 v0.24.0 起，解析器在角色加载时支持别名回退——角色可以引用能解析为具体模型的别名。</p></blockquote><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/rolebox-docs/03-Reference/role-yaml.html">role.yaml 参考</a> —— <code>model</code> 字段与其它字段的完整定义</li><li><a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a> —— 三个 harness 的目录布局与安装</li><li><a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a> —— <code>rolebox config</code> 交互式配置角色模型</li></ul>',25))])}const A=s(p,[["render",E]]);export{_ as __pageData,A as default};
